var maxRetries = 3;
var retryCount = Number(msg.emailRetryCount || 0);
var shouldFail = msg.emailSendError === true || msg.forceEmailFailure === true;

if (!shouldFail) {
    delete msg.emailRetryCount;
    delete msg.delayTimeout;
    return [msg, null, null];
}

if (retryCount < maxRetries - 1) {
    msg.emailRetryCount = retryCount + 1;
    msg.delayTimeout = Math.pow(2, retryCount) * 1000;
    node.warn('Email send failed, retry #' + msg.emailRetryCount + ' in ' + (msg.delayTimeout / 1000) + 's');
    return [null, null, msg];
}

msg.emailRetryCount = retryCount + 1;
msg.error = {
    message: 'Email send failed after ' + maxRetries + ' attempts'
};
return [null, msg, null];

var slots = [];
var advisors = [1, 2];
var now = new Date();

var startDate = new Date(now);
startDate.setHours(9, 0, 0, 0);
var dayOfWeek = startDate.getDay();
if (dayOfWeek === 0) startDate.setDate(startDate.getDate() + 1);
if (dayOfWeek === 6) startDate.setDate(startDate.getDate() + 2);
if (startDate.getHours() >= 9 && startDate.getMinutes() > 0) {
    startDate.setDate(startDate.getDate() + 1);
    startDate.setHours(9, 0, 0, 0);
}

for (var d = 0; d < 5; d++) {
    var slotDate = new Date(startDate);
    slotDate.setDate(slotDate.getDate() + d);
    if (slotDate.getDay() === 0 || slotDate.getDay() === 6) continue;
    for (var h = 9; h < 17; h++) {
        var start = new Date(slotDate);
        start.setHours(h, 0, 0, 0);
        var end = new Date(slotDate);
        end.setHours(h + 1, 0, 0, 0);
        var startStr = start.toISOString().replace('T', ' ').substring(0, 19);
        var endStr = end.toISOString().replace('T', ' ').substring(0, 19);
        for (var a = 0; a < advisors.length; a++) {
            slots.push('(' + advisors[a] + ', \'' + startStr + '\', \'' + endStr + '\')');
        }
    }
}

if (slots.length === 0) {
    msg.payload = { status: 'No business days found in next 5 days' };
    return msg;
}

msg.query = 'INSERT INTO booking_slot (advisor_id, start_time, end_time) VALUES\n    ' + slots.join(',\n    ') + '\nON CONFLICT (advisor_id, start_time, end_time) DO NOTHING;';
delete msg.payload;
delete msg.params;
delete msg.queryParameters;
return msg;
